(()=>{'use strict';
const KEY='summoner-scout.review.v1',SCHEMA=1;
const guides=[
 {title:"Summoner's Way",steps:['Return to your island.','Tap the Summoner’s Way icon on the island interface.'],reviewed:'2026-11-15'},
 {title:'Monster menu',steps:['Return to your island.','Tap Monster in the main island menu.'],reviewed:'2026-11-15'},
 {title:'Normal Monster Sealed Shrine',steps:['On your island, tap the Sealed Shrine building.','Choose the Normal tab.'],reviewed:'2026-11-15'},
 {title:'Profile records',steps:["On your island, open Summoner's Tower.",'Choose Profile to view records.'],reviewed:'2026-11-15'},
 {title:"Dragon's Lair",steps:['Open Battle.','Choose Cairos Dungeon.','Choose Dragon’s Lair and select a difficulty.'],reviewed:'2026-11-15'},
 {title:'Trial of Ascension',steps:['Open Battle.','Choose Trial of Ascension.','Select Normal or Hard.'],reviewed:'2026-11-15'}];
const blank=()=>({schemaVersion:SCHEMA,demoData:true,preferences:{pveOnly:true,f2p:true},toa:{mode:'Hard',current:37,best:61,target:50,notes:'Fictional demo team: Veromos / Fran / Loren / Spectra / Mav'},storage:{regular:{count:84,capacity:120},storage:{count:196,capacity:220},shrine:{count:73,capacity:100}},runs:[{id:'demo-dragon-1',dungeon:"Dragon's Lair",difficulty:'Abyss Hard',outcome:'Win',seconds:102.4,team:'Demo safe team',notes:'Fictional demonstration record',createdAt:'2026-11-12T18:00:00.000Z'},{id:'demo-dragon-2',dungeon:"Dragon's Lair",difficulty:'Abyss Hard',outcome:'Win',seconds:97.8,team:'Demo safe team',notes:'Fictional demonstration record',createdAt:'2026-11-12T18:05:00.000Z'},{id:'demo-dragon-3',dungeon:"Dragon's Lair",difficulty:'Abyss Hard',outcome:'Loss',seconds:null,team:'Demo safe team',notes:'Fictional demonstration record',createdAt:'2026-11-12T18:10:00.000Z'}],previousBest:{"Dragon's Lair|Abyss Hard":97.8},guideNotes:{},updatedAt:new Date().toISOString()});
let state=load(),page='home',pendingImport=null;
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?.schemaVersion===SCHEMA?{...blank(),...x}:blank()}catch{return blank()}}
function save(){state.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));toast('Saved locally');render()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
const nav=[['home','Home'],['toa','ToA'],['dungeons','Dungeons'],['storage','Storage'],['find','Find It']];
document.querySelector('nav').innerHTML=nav.map(([id,l])=>`<button data-page="${id}">${l}</button>`).join('');
document.querySelector('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render()}};
function percent(a,b){return b?Math.min(100,Math.round(a/b*100)):0}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#page-title').textContent=nav.find(x=>x[0]===page)[1];document.querySelector('#main').innerHTML=`<p class="warning"><strong>PUBLIC REVIEW BUILD</strong> — All visible records are fictional demonstration data. Changes stay only in this browser.</p>${({home,toa,dungeons,storage,find})[page]()}`;bind()}
function home(){const r=state.runs,w=r.filter(x=>x.outcome==='Win'),free=Object.values(state.storage).reduce((n,x)=>n+Math.max(0,x.capacity-x.count),0);return `<div class="grid"><section class="card span8 hero"><div class="eyebrow">WHAT SHOULD I DO NEXT?</div><h2>${state.toa.current<state.toa.target?`Push ToA ${esc(state.toa.mode)} toward floor ${state.toa.target}`:'Log a reliable dungeon farming set'}</h2><p>This suggestion comes from your own saved targets, not live game data.</p><button class="primary" data-go="${state.toa.current<state.toa.target?'toa':'dungeons'}">Open tracker</button></section><section class="card span4"><div class="eyebrow">PLAY STYLE</div><h2>PvE • Free to play</h2><p>Collecting, dungeons, ToA, Rift and achievements. PvP only when required.</p></section><section class="card span4"><h3>ToA ${esc(state.toa.mode)}</h3><div class="metric">Floor ${state.toa.current}</div><p>Best ${state.toa.best} · Target ${state.toa.target}</p><div class="progress"><span style="width:${percent(state.toa.current,state.toa.target)}%"></span></div></section><section class="card span4"><h3>Monster space</h3><div class="metric">${free} free</div><p>Across the three counters you maintain.</p></section><section class="card span4"><h3>Dungeon sample</h3><div class="metric">${w.length}/${r.length}</div><p>Wins logged. ${r.length<5?'Reliability is still untested.':'Enough data for an early trend.'}</p></section></div>`}
function toa(){const t=state.toa;return `<section class="card"><div class="eyebrow">ROTATION PROGRESS</div><h2>Trial of Ascension</h2><form id="toa-form" class="form-grid"><label>Mode<select name="mode"><option ${t.mode==='Normal'?'selected':''}>Normal</option><option ${t.mode==='Hard'?'selected':''}>Hard</option></select></label><label>Current floor<input name="current" type="number" min="0" max="100" value="${t.current}"></label><label>Historical best<input name="best" type="number" min="0" max="100" value="${t.best}"></label><label>Next milestone<input name="target" type="number" min="1" max="100" value="${t.target}"></label><label class="wide">Team notes<textarea name="notes">${esc(t.notes)}</textarea></label><div class="wide"><div class="progress"><span style="width:${percent(t.current,t.target)}%"></span></div><p>${Math.max(0,t.target-t.current)} floors to the next milestone. Historical best is kept separately.</p><button class="primary">Save ToA progress</button></div></form></section>`}
function dungeons(){const r=state.runs,w=r.filter(x=>x.outcome==='Win'),secs=w.map(x=>x.seconds),best=secs.length?Math.min(...secs):null,avg=secs.length?Math.round(secs.reduce((a,b)=>a+b,0)/secs.length):null;return `<div class="grid"><section class="card span6"><div class="eyebrow">QUICK ENTRY</div><h2>Log a dungeon run</h2><form id="run-form" class="form-grid"><label>Dungeon<input name="dungeon" required placeholder="Dragon's Lair"></label><label>Difficulty<input name="difficulty" required placeholder="Abyss Hard"></label><label>Outcome<select name="outcome"><option>Win</option><option>Loss</option></select></label><label>Clear time<input name="time" inputmode="decimal" placeholder="1:42.250"></label><label>Team label<input name="team" placeholder="Safe team"></label><label>Notes<input name="notes" placeholder="What changed?"></label><button class="primary wide">Save run</button></form></section><section class="card span6"><h2>Run summary</h2><div class="stat-row"><div class="stat"><b>${w.length}</b><small>Wins</small></div><div class="stat"><b>${r.length-w.length}</b><small>Losses</small></div><div class="stat"><b>${fmt(best)}</b><small>Best</small></div><div class="stat"><b>${fmt(avg)}</b><small>Win avg</small></div></div><p>${r.length<5?'Reliability untested — log at least five runs.':'This is a user-recorded trend, not a guarantee.'}</p><div class="list">${r.slice().reverse().slice(0,8).map(x=>`<div class="item row between"><span><b>${esc(x.dungeon)}</b> · ${esc(x.difficulty)}<br><small>${esc(x.team||'No team label')}</small></span><span class="pill">${x.outcome} ${fmt(x.seconds)}</span></div>`).join('')||'<div class="empty">No runs logged yet.</div>'}</div></section></div>`}
function fmt(s){if(s==null)return '—';return `${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`}
function storage(){const labels={regular:'Regular Monster Inventory',storage:'Monster Storage',shrine:'Normal Monster Sealed Shrine'};return `<section class="card"><div class="eyebrow">COUNTERS ONLY</div><h2>Monster space</h2><p>Editing these numbers does not move anything in the game.</p><form id="storage-form" class="grid">${Object.entries(labels).map(([k,l])=>{const x=state.storage[k];return `<div class="card span4"><h3>${l}</h3><div class="metric">${Math.max(0,x.capacity-x.count)} free</div><div class="progress"><span style="width:${percent(x.count,x.capacity)}%"></span></div><div class="form-grid"><label>Used<input name="${k}-count" type="number" min="0" value="${x.count}"></label><label>Capacity<input name="${k}-capacity" type="number" min="0" value="${x.capacity}"></label></div></div>`}).join('')}<button class="primary span12">Save all counters</button></form></section>`}
function find(){return `<section class="card"><div class="eyebrow">CURRENT UI MAY VARY</div><h2>Where is it?</h2><label>Search navigation tips<input id="guide-search" type="search" placeholder="Dragon, storage, profile…"></label><p class="warning">Do not tap the decorative diamond beside a Storage count—it is not a button.</p><div id="guide-list" class="list">${guideHtml(guides)}</div></section>`}
function guideHtml(list){return list.map((g,i)=>`<article class="item guide"><button aria-expanded="true"><h3>${esc(g.title)}</h3></button><ol>${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>Last reviewed ${g.reviewed}. May vary after updates.</p><label>Your correction or note<textarea data-guide="${i}">${esc(state.guideNotes[i]||'')}</textarea></label><button class="ghost" data-save-guide="${i}">Save note</button></article>`).join('')||'<div class="empty">No matching tips.</div>'}
function parseTime(v){if(!v)return null;const m=v.trim().match(/^(?:(\d+):)?(\d{1,2})(?:\.(\d{1,3}))?$/);if(!m)return NaN;return +(Number(m[1]||0)*60+Number(m[2])+Number(`0.${m[3]||0}`)).toFixed(3)}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{page=b.dataset.go;render()});const tf=document.querySelector('#toa-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const f=new FormData(tf);state.toa={mode:f.get('mode'),current:+f.get('current'),best:+f.get('best'),target:+f.get('target'),notes:f.get('notes')};save()};const rf=document.querySelector('#run-form');if(rf)rf.onsubmit=e=>{e.preventDefault();const f=new FormData(rf),seconds=parseTime(f.get('time'));if(Number.isNaN(seconds))return toast('Use time like 1:42.250');state.runs.push({id:crypto.randomUUID(),dungeon:f.get('dungeon'),difficulty:f.get('difficulty'),outcome:f.get('outcome'),seconds,team:f.get('team'),notes:f.get('notes'),createdAt:new Date().toISOString()});if(f.get('outcome')==='Win'&&seconds!=null){const k=`${f.get('dungeon')}|${f.get('difficulty')}`,old=state.previousBest[k];state.previousBest[k]=old==null?seconds:Math.min(old,seconds)}save()};const sf=document.querySelector('#storage-form');if(sf)sf.onsubmit=e=>{e.preventDefault();const f=new FormData(sf);for(const k of Object.keys(state.storage)){state.storage[k]={count:+f.get(`${k}-count`),capacity:+f.get(`${k}-capacity`)}}save()};const q=document.querySelector('#guide-search');if(q)q.oninput=()=>{const s=q.value.toLowerCase();document.querySelector('#guide-list').innerHTML=guideHtml(guides.filter(g=>`${g.title} ${g.steps}`.toLowerCase().includes(s)));bind()};document.querySelectorAll('[data-save-guide]').forEach(b=>b.onclick=()=>{const i=b.dataset.saveGuide;state.guideNotes[i]=document.querySelector(`[data-guide="${i}"]`).value;save()})}
const installStyles=document.createElement('link');installStyles.rel='stylesheet';installStyles.href='install.css';document.head.append(installStyles);let installPrompt=null;const installButton=document.querySelector('#install-btn'),installHelp=document.querySelector('#install-help');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;installButton.hidden=false});installButton.onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();const result=await installPrompt.userChoice;if(result.outcome==='accepted')toast('Summoner Scout installed');installPrompt=null;installButton.hidden=true};if(/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches&&!localStorage.getItem('summoner-scout.install-dismissed'))installHelp.hidden=false;document.querySelector('#dismiss-install').onclick=()=>{installHelp.hidden=true;localStorage.setItem('summoner-scout.install-dismissed','1')};window.addEventListener('appinstalled',()=>{installButton.hidden=true;installHelp.hidden=true;toast('App installed')});const dlg=document.querySelector('#backup-dialog');document.querySelector('#backup-btn').onclick=()=>dlg.showModal();document.querySelector('#export-btn').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download=`summoner-scout-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)};document.querySelector('#import-file').onchange=async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(x.schemaVersion!==SCHEMA)throw Error();pendingImport=x;const p=document.querySelector('#import-preview');p.hidden=false;p.innerHTML=`<h3>Import preview</h3><p>ToA ${esc(x.toa?.mode)} floor ${x.toa?.current}; ${x.runs?.length||0} dungeon runs. This will replace local data.</p>`;document.querySelector('#confirm-import').hidden=false}catch{toast('That is not a valid v1 backup')}};document.querySelector('#confirm-import').onclick=()=>{if(!pendingImport)return;state={...blank(),...pendingImport};save();dlg.close()};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');render();
})();

